import Foundation

/// A part of the model the helper installs and removes on its own
/// (openspec add-cloud-meeting-asr, D3): the recognizer, or the speaker
/// separator that cloud providers also use.
public enum ModelComponent: String, CaseIterable, Comparable, CodingKeyRepresentable, Decodable, Sendable {
    case asr
    case diarization

    public static let all = Set(allCases)

    public static func < (lhs: ModelComponent, rhs: ModelComponent) -> Bool {
        allCases.firstIndex(of: lhs)! < allCases.firstIndex(of: rhs)!
    }
}

/// The pinned model files, generated by
/// `clients/apps/electron/scripts/transcriber-models-manifest.ts` and compiled
/// into the helper. An install is accepted only when it matches this list.
public struct ModelManifest: Decodable, Sendable, Equatable {
    public struct Repo: Decodable, Sendable, Equatable {
        public let repo: String
        public let revision: String
        /// FluidAudio's `Repo.folderName` under the models root.
        public let folder: String
        /// `ModelHub.download` variant.
        public let variant: String
    }

    public struct File: Decodable, Sendable, Equatable {
        public let path: String
        public let size: Int64
        public let sha256: String

        public init(path: String, size: Int64, sha256: String) {
            self.path = path
            self.size = size
            self.sha256 = sha256
        }
    }

    /// Name of the installed folder under the models directory. A subset
    /// keeps it: every component installs into the same folder.
    public let id: String
    public let repos: [Repo]
    /// Top-level folders of each component.
    public let components: [ModelComponent: [String]]
    public let files: [File]

    public init(id: String, repos: [Repo], components: [ModelComponent: [String]], files: [File]) {
        self.id = id
        self.repos = repos
        self.components = components
        self.files = files
    }

    public var totalBytes: Int64 { files.reduce(0) { $0 + $1.size } }

    public func bytes(of component: ModelComponent) -> Int64 { subset([component]).totalBytes }

    /// The repositories and files of `components` only.
    public func subset(_ selected: Set<ModelComponent>) -> ModelManifest {
        let components = self.components.filter { selected.contains($0.key) }
        let folders = Set(components.values.joined())
        return ModelManifest(
            id: id,
            repos: repos.filter { folders.contains($0.folder) },
            components: components,
            files: files.filter { file in folders.contains(where: { file.path.hasPrefix($0 + "/") }) })
    }

    public static func bundled() throws -> ModelManifest {
        try JSONDecoder().decode(ModelManifest.self, from: Data(PackageResources.models_manifest_json))
    }
}
